$(function () {
	const servicesSlider = new Swiper('.js-services-slider', {
		slidesPerView: 'auto',
		speed: 1200,
		breakpoints: {
			1280: {
				enabled: false,
			}
		}
	});

	const infoThumbs = new Swiper('.js-info-thumbs', {
		slidesPerView: 'auto',
		watchSlidesProgress: true,
	});

	const infoSlider = new Swiper('.js-info-slider', {
		speed: 1200,
		thumbs: {
			swiper: infoThumbs,
		},
	});

	const popupInfoThumbs = new Swiper('.js-popup-info-thumbs', {
		slidesPerView: 'auto',
		watchSlidesProgress: true,
	});

	const popupInfoSlider = new Swiper('.js-popup-info-slider', {
		speed: 1200,
		thumbs: {
			swiper: popupInfoThumbs,
		},
	});

	const tariffsThumbs = new Swiper('.js-tariffs-thumbs', {
		slidesPerView: 'auto',
		watchSlidesProgress: true,
	});

	const tariffsSlider = new Swiper('.js-tariffs-slider', {
		slidesPerView: 'auto',
		speed: 1200,
		// effect: 'fade',
    // fadeEffect: {
    //   crossFade: true
    // },
    autoplay: {
      delay: 5000,
      disableOnInteraction: false,
			waitForTransition: false
    },
		thumbs: {
			swiper: tariffsThumbs,
		},
	});

	const similarSlider = new Swiper('.js-similar-slider', {
		slidesPerView: 'auto',
		speed: 1200,
		breakpoints: {
			1024: {
				slidesPerView: 3,
			}
		}
	});

	const journalSlider = new Swiper('.js-journal-slider', {
		speed: 1200,
		loop: true,
		loopedSlides: 3,
		direction: 'vertical',
		effect: 'cards',
		grabCursor: true,
		autoplay: {
			delay: 5000,
			disableOnInteraction: false,
			waitForTransition: false
		},
		on: {
			setTranslate(swiper) {
				swiper.slides.forEach((slide) => {
					let currentTransform = slide.style.transform;
					currentTransform = currentTransform.replace(/rotateZ\([^)]+\)/g, '').replace(/rotate\([^)]+\)/g, '');
					currentTransform = currentTransform.replace(/translate3d\(([^,]+),\s*([^,]+),\s*([^)]+)\)/g, 'translate3d(0px, $2, $3)');
					slide.style.transform = currentTransform;
				});
			}
		},
		pagination: {
			el: '.journal__slider-pagination',
			clickable: true,
			renderBullet: function (index, className) {
				return `
					<span class="${className}">
						<svg xmlns="http://www.w3.org/2000/svg" width="15" height="15" viewBox="0 0 15 15" fill="none">
							<path d="M7.5 0.5H0.5V14.5H14.5V0.5H7.50178" stroke="#EB432F"/>
						</svg>
					</span>
				`;
			},
		},
	});

	$('.js-project-slider').each(function () {
		const slidesCount = $(this).find('.swiper-slide').length;

		if (slidesCount < 3) {
			$(this).addClass('js-project-slider-small project__slider_small');
		}
	});

	const projectSlider = new Swiper('.js-project-slider:not(.js-project-slider-small)', {
		slidesPerView: 1.09,
		spaceBetween: 10,
		speed: 1200,
		breakpoints: {
			768: {
				slidesPerView: 2,
				spaceBetween: 10,
			},
			1280: {
				slidesPerView: 3,
				spaceBetween: 10,
			},
			1601: {
				slidesPerView: 3,
				spaceBetween: 15,
			}
		}
	});

	const projectSliderSmall = new Swiper('.js-project-slider-small', {
		slidesPerView: 1.09,
		spaceBetween: 10,
		speed: 1200,
		breakpoints: {
			768: {
				slidesPerView: 2,
				spaceBetween: 10,
			},
			1280: {
				enabled: false,
				slidesPerView: 'auto',
				spaceBetween: 0,
			},
			1601: {
				enabled: false,
				slidesPerView: 'auto',
				spaceBetween: 0,
			}
		}
	});

	const historySlider = new Swiper('.js-history-slider', {
		slidesPerView: 1.07,
		spaceBetween: 10,
		speed: 1200,
		breakpoints: {
			768: {
				enabled: true,
				slidesPerView: 1.66,
				spaceBetween: 20,
			},
			1280: {
				enabled: false,
				slidesPerView: 1,
				spaceBetween: 0,
			}
		}
	});
})