$(function () {
	const filesAll = document.querySelectorAll('.js-file');

	if (filesAll) {
		filesAll.forEach(item => {
			const fileInput = item.querySelector('.js-file-input');
			const fileDocument = item.querySelector('.js-file-document');
			let dataTransfer = new DataTransfer();

			function createItemHTML(fileName) {
				return `
					<div class="file__document-item">
						<div class="file__document-item-title">${fileName}</div>
						<button type="button" class="file__document-item-delete js-file-document-delete" data-delete="${fileName}" aria-label="Удалить файл">
							<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 16 16">
								<path d="M9.42857 8L13 11.5714L11.5714 13L8 9.42857L4.42857 13L3 11.5714L6.57143 8L3 4.42857L4.42857 3L8 6.57143L11.5714 3L13 4.42857L9.42857 8Z"/>
							</svg>
						</button>
					</div>
				`;
			}

			function updateFiles() {
				fileDocument.innerHTML = '';
				Array.from(dataTransfer.files).forEach(file => {
					fileDocument.insertAdjacentHTML('beforeend', createItemHTML(file.name));
				});
				fileInput.files = dataTransfer.files;
			}

			fileInput.addEventListener('change', (e) => {
				Array.from(e.target.files).forEach(file => {
					const isExist = Array.from(dataTransfer.files).some(f => f.name === file.name && f.size === file.size);
					if (!isExist) {
						dataTransfer.items.add(file);
					}
				});
				updateFiles();
			});

			item.addEventListener('click', (e) => {
				const deleteButton = e.target.closest('.js-file-document-delete');
				if (!deleteButton) return;

				const fileNameToDelete = deleteButton.dataset.delete;
				const fileIndex = Array.from(dataTransfer.files).findIndex(file => file.name === fileNameToDelete);

				if (fileIndex !== -1) {
					dataTransfer.items.remove(fileIndex);
				}

				updateFiles();
			});
		});
	}
})