$(function () {
  if ($('.js-services').length) {
    // gsap.registerPlugin(ScrollTrigger, MorphSVGPlugin);
    
    const isMobile = () => window.innerWidth < 1280;

    const svgItem = $('.services__decor-svg');
    const svgTargets = $('.services__decor-target');
    const gallery = $('.services__media-item');
    const scrollItems = $('.js-services-item');

    scrollItems.each(function(index, element) {
      const targetSvg = svgTargets.eq(index).attr('d');
      const targetGallery = gallery.eq(index);

      ScrollTrigger.create({
        trigger: element,
        start: 'top center',
        end: 'bottom center',
        onToggle: (self) => {
          if (isMobile()) return;

          if (self.isActive) {
            gsap.to(svgItem, {
              morphSVG: targetSvg,
              duration: 1,
              overwrite: 'auto'
            });
          }
        }
      });

      $(element).hover(
        () => {
          if (isMobile()) return;

          gsap.to(targetGallery, {
            autoAlpha: 1,
            duration: .3,
            overwrite: 'auto'
          });
        },
        () => {
          if (isMobile()) return;
          
          gsap.to(targetGallery, {
            autoAlpha: 0,
            duration: .3,
            overwrite: 'auto'
          });
        }
      );
    });

    const mm = gsap.matchMedia();

    mm.add({
      isSmallDesktop: '(min-width: 1280px) and (max-width: 1599px)',
      isLargeDesktop: '(min-width: 1600px)'
    }, (context) => {
      const { isSmallDesktop } = context.conditions;
      const maskXPosition = isSmallDesktop ? '80px' : '115px';

      const tl = gsap.timeline({
        scrollTrigger: {
          trigger: '.services',
          start: 'bottom bottom',
          end: () => `+=${window.innerHeight * 2}`,
          pin: true,
          pinSpacing: false,
          scrub: 1,
        }
      });

      // tl.to(svgItem, {
      //   morphSVG: svgTargets.eq(0).attr('d'),
      //   duration: .1,
      //   // overwrite: 'auto'
      // })

      tl.to('.services__decor', {
        autoAlpha: 0,
        duration: .25,
      })
      .from('.services__shape', {
        autoAlpha: 0,
        duration: .25,
      }, '>')
      .fromTo('.services__shape', {
        maskSize: '98px',
        maskPosition: `${maskXPosition} calc(100% - 38px)`,
        duration: 1,
      }, {
        maskSize: '100vw',
        maskPosition: '0px calc(100% - 0px)',
        duration: 1,
      })
      .to('.services__shape', {
        maskSize: '400vw',
        maskPosition: '0px 33%',
        duration: .25,
      })
      // tl.to({}, { duration: 1.5 });
      .from('.about__img', {
        autoAlpha: 0,
        duration: .1,
      }, '<+.1')
      .to('.services', {
        autoAlpha: 0,
        duration: .1,
      })
      .from('.about__inner', {
        autoAlpha: 0,
        duration: .5,
      }, '<-.1');
    });
  }
});