$(function() {
	let header = $('.js-header');
	const scrollWidth = window.innerWidth - $('body')[0].offsetWidth + 'px';

  function showScroll() {
    if (!/iPhone|iPad|iPod|Android/i.test(navigator.userAgent)) {
      $('body').css('padding-right', '');
      header.css('right', '');
    }
    $('body').removeClass('o-hidden');
		window.lenis.start();
  }

  function hideScroll() {
    if (!/iPhone|iPad|iPod|Android/i.test(navigator.userAgent)) {
      $('body').css('padding-right', scrollWidth);
      header.css('right', scrollWidth);
    }
    $('body').addClass('o-hidden');
		window.lenis.stop();
  }

	function closeModal() {
		// $('.popup').removeClass('popup_active').find('.popup__content').removeAttr('style');
		$('.popup').removeClass('popup_active').find('.popup__content').css({ top: '', left: '', width: '', alignSelf: '' })
			.find('.popup__inner').css({ maxHeight: '' });
		showScroll();
		if ($('.js-burger').hasClass('burger_active')) {
			hideScroll();
		}
	}

	$('.js-popup-up').click(function (e) {
		e.preventDefault();
		let modal = $(this).data('target');
		$(modal).addClass('popup_active');
		hideScroll();
	});

	$('.js-popup-close').click(function (e) {
		e.preventDefault();
		closeModal();
	});

	$('.js-popup-tab-item').click(function () {
		$('.js-popup-tab-item').removeClass('popup__tab-item_active');
		$(this).addClass('popup__tab-item_active');
		const data = $(this).data('tab');
		$('.js-popup-tab-block').removeClass('popup__tab-block_active');
		const activeBlock = $(`.js-popup-tab-block[data-tab='${data}']`);
		activeBlock.addClass('popup__tab-block_active');
		const targetForm = activeBlock.find('form').attr('id');
		$('.js-popup-form-bind').attr('form', targetForm);
	});

	$(document).mousedown(function (e) {
		let popupActive = $('.popup_active');
		if (popupActive.length === 0) return;

		let targetBlock = popupActive.find('.popup__wrap');
		if (targetBlock.has(e.target).length === 0) {
			closeModal();
		}
	});

	$(document).keydown(function (e) {
		if ($('.popup').hasClass('popup_active') && e.code === 'Escape') {
			closeModal();
		}
	});

	let buttonChek = null;
	$('.header .js-popup-up').click(function () {
		if (window.innerWidth > 1279) {
			buttonChek = $(this);
			const target = $(this).data('target');
			const rect = this.getBoundingClientRect();
			const top = Math.round(rect.top);
			const left = Math.round(rect.left);
			const width = rect.width;

			$(target).find('.popup__content').css({
				top: top + 'px',
				left: left + 'px',
				width: width + 'px',
				alignSelf: 'flex-start'
			}).find('.popup__inner').css({
				maxHeight: `calc(100vh - ${top * 2}px)`
			});
		}
	});

	let resizeTimeout;
	$(window).on('resize', function () {
		clearTimeout(resizeTimeout);

		resizeTimeout = setTimeout(function () {
			if (buttonChek && window.innerWidth < 1280) {
				$(buttonChek.data('target')).find('.popup__content').css({ top: '', left: '', width: '', alignSelf: '' })
					.find('.popup__inner').css({ maxHeight: '' });
				buttonChek = null;
			}
		}, 100);
	});
})