$(function () {
  if ($('.hero').length) {
    // gsap.registerPlugin(SplitText, MorphSVGPlugin);

    let prevIndex = 0;
    let isAnimating = false;
    let autoplayAnimation = null;
    const autoplayDelay = 7;

    const tabItem = $('.hero__tab');
    const textItem = $('.hero__text');
    const gallery = $('.hero').find('.gallery__item');
    const galleryThumbs = $('.hero').find('.gallery__thumbs-item');
    const svgItem = $('.hero__decor-svg');
    const svgTargets = $('.hero__decor-target');

    const mm = gsap.matchMedia();
    let isDesktop = true;

    mm.add({
      isDesktop: '(min-width: 768px)',
      isMobile: '(max-width: 767px)'
    }, (context) => {
      isDesktop = context.conditions.isDesktop;

      const currentIndex = $('.hero__tab.active').index();
      if (currentIndex !== -1) {
        prevIndex = currentIndex;
      }

      isAnimating = false;

      textItem.removeClass('active');
      textItem.eq(prevIndex).addClass('active');

      gsap.set('.hero__title', { clearProps: 'all' });

      galleryThumbs.css('display', 'none');
      galleryThumbs.filter(`[data-gallery='${prevIndex}']`).css('display', 'block');

      const targetSvg = svgTargets.eq(prevIndex).attr('d');
      gsap.set(svgItem, {
        morphSVG: targetSvg
      });

      resetAutoplay();
      startAutoplay(prevIndex);
    });

    function changeSlide(index) {
      if (isAnimating || index === prevIndex) return;
      isAnimating = true;

      resetAutoplay();
      startAutoplay(index);

      const prevText = textItem.eq(prevIndex);
      const prevTitle = prevText.find('.hero__title');
      const prevDescription = prevText.find('.hero__description');
      const text = textItem.eq(index);
      const title = text.find('.hero__title');
      const description = text.find('.hero__description');

      const prevGalleryItem = gallery.filter(`[data-gallery='${prevIndex}']`);
      const galleryItem = gallery.filter(`[data-gallery='${index}']`);
      const prevGalleryThumbsItem = galleryThumbs.filter(`[data-gallery='${prevIndex}']`);
      const galleryThumbsItem = galleryThumbs.filter(`[data-gallery='${index}']`);

      const targetSvg = svgTargets.eq(index).attr('d');

      tabItem.removeClass('active').eq(index).addClass('active');

      const tl = gsap.timeline({
        onComplete: () => {
          prevIndex = index;
          isAnimating = false;

          // prevSplit.revert();
          if (isDesktop && prevSplit) {
            prevSplit.revert();
          }
        }
      });

      let prevSplit = null;
      let split = null;

      if (isDesktop) {
        prevSplit = SplitText.create(prevTitle[0], { type: 'chars' });
      }
      
      tl.fromTo(prevTitle[0], {
        duration: .5,
        y: '0%',
      }, {
        y: '-100%',
      })
      // tl.to(prevTitle[0], {
      //   duration: .5,
      //   y: '-100%',
      // })
      if (isDesktop) {
        tl.to(prevSplit.chars, {
          duration: .5,
          y: '-25%',
          stagger: {
            each: 0.05,
            from: 'end'
          },
        }, 0)
      }
      tl.to(prevDescription, {
        duration: .25,
        autoAlpha: 0,
      }, '<')
      .add(() => {
        prevText.removeClass('active');
      }, .5);

      text.addClass('active');

      if (isDesktop) {
        split = SplitText.create(title[0], { type: 'chars' });
      }

      tl.fromTo(title[0], {
        duration: .5,
        y: '100%',
      }, {
        y: '0%',
      }, 0)
      // tl.from(title[0], {
      //   duration: .5,
      //   y: '100%',
      // }, 0)
      if (isDesktop) {
        tl.from(split.chars, {
          duration: .5,
          y: '25%',
          stagger: 0.05,
        }, 0)
      }
      tl.fromTo(description,
        { autoAlpha: 0 }, 
        { autoAlpha: 1, duration: .25 }, 
        '>-.5'
      );

      tl.set([prevGalleryItem, prevGalleryThumbsItem], {
        display: 'none'
      }, 0)
      .set([galleryItem, galleryThumbsItem], {
        display: 'block'
      }, 0);

      tl.to(svgItem, {
        morphSVG: targetSvg,
        duration: tl.duration(),
      }, 0);

      const tabs = $('.hero__tabs');
      const activeTab = tabItem.eq(index);

      if (activeTab.length) {
        const tabsWidth = tabs.width();
        const tabWidth = activeTab.outerWidth();
        const tabLeft = activeTab.position().left + tabs.scrollLeft();

        const scrollToX = tabLeft - (tabsWidth / 2) + (tabWidth / 2);

        tabs.stop().animate({
          scrollLeft: scrollToX
        }, 0);
      }
    }

    function startAutoplay(i) {
      if (autoplayAnimation) return;

      const targetIndex = i !== undefined ? i : prevIndex;
      const activeProgress = tabItem.eq(targetIndex).find('.hero__tab-progress');

      autoplayAnimation = gsap.to(activeProgress, {
        width: '100%',
        duration: autoplayDelay,
        ease: 'none',
        onComplete: function() {
          let nextIndex = prevIndex + 1;
          if (nextIndex >= tabItem.length) {
            nextIndex = 0;
          }
          changeSlide(nextIndex);
        }
      });
    }

    function resetAutoplay() {
      if (autoplayAnimation) {
        autoplayAnimation.kill();
        autoplayAnimation = null;
      }
      gsap.set('.hero__tab-progress', { width: '0%' });
    }

    tabItem.click(function () {
      changeSlide($(this).index());
    });

    startAutoplay();
  }
})