$(function () {
	if ($('.js-marquee').length) {
		$('.js-marquee').each(function () {
			const title = $(this);
			const titleText = title.text().trim();
			const mm = gsap.matchMedia();

			mm.add('(max-width: 767px)', () => {
				title.addClass('marquee');

				let titleTextRepeated = '';
				for (let i = 0; i < 5; i++) {
					titleTextRepeated += `<span aria-hidden="true">${titleText}</span>`;
				}
				title.attr('aria-label', titleText).html(titleTextRepeated);

				const spans = title.find('span');
				const stepWidth = spans.eq(0).outerWidth(true);

				gsap.to(spans, {
					x: -stepWidth,
					duration: 5,
					ease: 'none',
					repeat: -1
				});

				return () => {
					title.removeClass('marquee').removeAttr('aria-label').html(titleText);
				};
			});
		});
	}
})