$(function () {
	if ($('.js-clients-ticker').length) {
		const ticker = $('.js-clients-ticker');
		const tickerContent = $('.clients__ticker-wrapper');
		const tickerItems = tickerContent.find('.clients__ticker-item');
		const tickerCount = tickerItems.length;
		
		tickerContent.append(tickerItems.clone());
		
		let tl;
		let mm = gsap.matchMedia();
		let isDesktopCheck = false;

		mm.add({
			isDesktop: '(min-width: 1280px)',
			isTablet: '(min-width: 768px) and (max-width: 1279px)',
			isMobile: '(max-width: 767px)'
		}, (context) => {
			let { isDesktop, isTablet, isMobile } = context.conditions;
			isDesktopCheck = isDesktop;
			
			let tickerWidth = 0;
			tickerItems.each(function () {
				tickerWidth += $(this).outerWidth(true);
			});

			let currentDuration = tickerCount * 5;
			// if (isTablet) currentDuration = tickerCount * 4;
			// if (isMobile) currentDuration = tickerCount * 3;

			tl = gsap.to(tickerContent, {
				x: -tickerWidth,
				duration: currentDuration,
				ease: 'none',
				repeat: -1
			});
		});

		ticker.hover(
			() => {
				if (!tl || !isDesktopCheck) return;
				gsap.to(tl, { timeScale: 0, duration: 0.5, ease: 'power1.out' });
			},
			() => {
				if (!tl || !isDesktopCheck) return;
				gsap.to(tl, { timeScale: 1, duration: 0.5, ease: 'power1.out' });
			}
		);
	}
})