$(function () {
  if ($('.js-history').length) {
    // gsap.registerPlugin(ScrollTrigger);

    const section = $('.js-history');
    const title = $('.js-history-title');
    const cards = $('.js-history-item');
    const mediaItem = $('.js-history-media-item');

    let mm = gsap.matchMedia();

    mm.add('(min-width: 1280px)', () => {
      gsap.set(cards, { y: '100vh' });

      const tl = gsap.timeline({
        scrollTrigger: {
          trigger: section,
          start: 'top top',
          end: () => `+=${cards.length * 100}%`,
          pin: true,
          scrub: 1,
          invalidateOnRefresh: true
        }
      });

      tl.from(title, {
        opacity: 1,
        color: '#EB432F',
        duration: .5,
      });

      cards.each(function (index, card) {
        tl.to(card, {
          y: 0,
          duration: 1,
        }, index === 0 ? '<-.5' : null)

        if (index > 0) {
          tl.to(cards.slice(0, index), {
            y: (i) => (index - i) * -4,
            scaleX: (i) => 1 - (index - i) * 0.025,
            backgroundColor: '#CED0DB',
            duration: .5,
          }, '>-.5')
        }
      });

      tl.from(mediaItem, {
        autoAlpha: 0,
        duration: .5,
        stagger: .15,
      });
    });
  }
});